<?php use App\Support\Env;use App\Support\View;$base=rtrim((string)Env::get('APP_BASE_PATH',''),'/');$url=$base.'/admin/partidas/'.$match['id'].'/'.$mode; ?>
<main id="conteudo" class="content dashboard-page"><header class="topbar"><div><span class="eyebrow"><?=View::e($match['tournament_name'])?> · <?=View::e($match['stage_name']??'Fase')?></span><h1><?=View::e($match['home_name'])?> <?=$match['home_score']?> x <?=$match['away_score']?> <?=View::e($match['away_name'])?></h1><p><?=View::e((string)$match['scheduled_at'])?> · <?=View::e((string)$match['group_name'])?> · <?=View::e($match['status'])?></p></div></header><nav class="tabs"><a href="<?=$base?>/admin/partidas/<?=$match['id']?>">Detalhes</a><a href="<?=$base?>/admin/partidas/<?=$match['id']?>/escalacao">Escalacao</a><a href="<?=$base?>/admin/partidas/<?=$match['id']?>/operar">Central</a><a href="<?=$base?>/admin/partidas/<?=$match['id']?>/homologacao">Homologacao</a><a href="<?=$base?>/admin/partidas/<?=$match['id']?>/retificacao">Retificacao</a><a href="<?=$base?>/admin/partidas/<?=$match['id']?>/sumula">Sumula</a></nav>
<?php if($mode==='operar'):?><section class="panel"><h2>Central da partida</h2><form method="post" action="<?=$url?>"><input type="hidden" name="_csrf" value="<?=View::e($csrf)?>"><input type="hidden" name="action" value="event"><label>Acao<select name="event_type"><option>start</option><option>halftime</option><option>second_half</option><option>goal</option><option>own_goal</option><option>assist</option><option>yellow</option><option>second_yellow</option><option>red</option><option>substitution</option><option>incident</option></select></label><label>Equipe<select name="team_id"><?php foreach([(int)$match['home_team_id']=>$match['home_name'],(int)$match['away_team_id']=>$match['away_name']]as$id=>$name):?><option value="<?=$id?>"><?=View::e($name)?></option><?php endforeach;?></select></label><label>Atleta<select name="person_id"><option value="">Sem atleta</option><?php foreach($players as$team):foreach($team as$p):?><option value="<?=$p['id']?>"><?=View::e($p['full_name'])?></option><?php endforeach;endforeach;?></select></label><label>Minuto<input name="minute" type="number" min="0" max="150"></label><label>Periodo<select name="period"><option value="first">1o tempo</option><option value="second">2o tempo</option><option value="extra_first">Prorrogacao 1</option><option value="extra_second">Prorrogacao 2</option></select></label><button class="button">Registrar evento</button></form><form method="post" action="<?=$url?>"><input type="hidden" name="_csrf" value="<?=View::e($csrf)?>"><input type="hidden" name="action" value="finish"><button class="button">Finalizar para homologacao</button></form></section>
<?php elseif($mode==='homologacao'):?><section class="panel"><h2>Checklist de homologacao</h2><ul><li>Escalacoes: <?=count($lineups)?></li><li>Eventos: <?=count($events)?></li><li>Placar: <?=$match['home_score']?> x <?=$match['away_score']?></li></ul><form method="post" action="<?=$url?>"><input type="hidden" name="_csrf" value="<?=View::e($csrf)?>"><input type="hidden" name="action" value="homologate"><button class="button">Homologar partida</button></form></section>
<?php elseif($mode==='retificacao'):?><section class="panel"><h2>Solicitar retificacao</h2><form method="post" action="<?=$url?>"><input type="hidden" name="_csrf" value="<?=View::e($csrf)?>"><input type="hidden" name="action" value="rectify"><label>Motivo<textarea required name="reason"></textarea></label><button class="button">Solicitar analise</button></form><?php foreach($requests as$r):?><p><?=View::e($r['status'])?> · <?=View::e($r['reason'])?></p><?php endforeach;?></section>
<?php elseif($mode==='sumula'):?><section class="panel"><h2>Sumula digital</h2><p>Versao oficial, placar e cronologia persistidos. PDF individual disponivel apos homologacao.</p></section>
<?php else:?><section class="panel"><h2>Detalhes administrativos</h2><p>Rodada: <?=View::e((string)$match['round_name'])?> · Grupo: <?=View::e((string)$match['group_name'])?></p></section><?php endif;?><section class="panel"><h2>Cronologia</h2><ol class="event-timeline"><?php foreach($events as$e):?><li><time><?=View::e((string)$e['minute'])?>'</time><strong><?=View::e($e['event_type'])?></strong> <?=View::e((string)$e['team_name'])?> · <?=View::e((string)$e['full_name'])?></li><?php endforeach;?></ol></section></main>
